package com.campus.personnel.api;
import java.time.Instant; import java.util.*; import com.campus.personnel.application.FacultyStaffManagementService; import com.campus.personnel.domain.*; import jakarta.validation.*; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.support.ServletUriComponentsBuilder;
@RestController @RequestMapping("/api/v1/admin/faculty-staff") public class AdminFacultyStaffController { private final FacultyStaffManagementService service; public AdminFacultyStaffController(FacultyStaffManagementService s){service=s;} @PostMapping public ResponseEntity<Response> create(@Valid @RequestBody Request r){FacultyStaffMember m=service.create(r.personnelNumber(),r.fullName(),r.email(),r.personnelType(),r.organizationUnitId(),r.status());return ResponseEntity.created(ServletUriComponentsBuilder.fromCurrentRequest().path("/{memberId}").buildAndExpand(m.id()).toUri()).body(out(m));} @GetMapping public List<Response> list(){return service.list().stream().map(AdminFacultyStaffController::out).toList();} @GetMapping("/{memberId}") public Response get(@PathVariable UUID memberId){return out(service.get(memberId));} @PutMapping("/{memberId}") public Response update(@PathVariable UUID memberId,@Valid @RequestBody UpdateRequest r){return out(service.update(memberId,r.personnelNumber(),r.fullName(),r.email(),r.personnelType(),r.organizationUnitId(),r.status(),r.expectedVersion()));} private static Response out(FacultyStaffMember m){return new Response(m.id(),m.personnelNumber(),m.fullName(),m.email(),m.personnelType().name(),m.organizationUnitId(),m.status().name(),m.rowVersion(),m.createdAt(),m.updatedAt());} public record Request(@NotBlank String personnelNumber,@NotBlank String fullName,String email,@NotNull PersonnelType personnelType,@NotNull UUID organizationUnitId,PersonnelStatus status){} public record UpdateRequest(@NotBlank String personnelNumber,@NotBlank String fullName,String email,@NotNull PersonnelType personnelType,@NotNull UUID organizationUnitId,@NotNull PersonnelStatus status,@NotNull @PositiveOrZero Long expectedVersion){} public record Response(UUID id,String personnelNumber,String fullName,String email,String personnelType,UUID organizationUnitId,String status,long rowVersion,Instant createdAt,Instant updatedAt){} }
